import{_ as t,a,b as s,c as r}from"./chunks/package-import-297.C0Lrc5sP.js";import{_ as i,o as n,c as o,a3 as l}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"Appareils et tablette","description":"Tuiles, marqueurs sur plan, retour de tablette et capacités des paquets dans Studio 0.1.297.","frontmatter":{"title":"Appareils et tablette","description":"Tuiles, marqueurs sur plan, retour de tablette et capacités des paquets dans Studio 0.1.297."},"headers":[],"relativePath":"fr/projects/grafik-visual-studio/devices-tablet.md","filePath":"fr/projects/grafik-visual-studio/devices-tablet.md","lastUpdated":1794133462000}'),u={name:"fr/projects/grafik-visual-studio/devices-tablet.md"};function d(c,e,p,m,g,h){return n(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="appareils-et-tablette" tabindex="-1">Appareils et tablette <a class="header-anchor" href="#appareils-et-tablette" aria-label="Permalink to &quot;Appareils et tablette&quot;">​</a></h1><p><strong>Studio 0.1.297</strong> ajoute le groupe intégré <strong>Appareils</strong> dans la palette. Aucune installation de paquet supplémentaire nécessaire. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/releases/tag/grafik-visual-studio-v0.1.297" target="_blank" rel="noreferrer">Mise à jour GitHub</a>.</p><h2 id="ajouter-des-appareils" tabindex="-1">Ajouter des appareils <a class="header-anchor" href="#ajouter-des-appareils" aria-label="Permalink to &quot;Ajouter des appareils&quot;">​</a></h2><p>Développer le groupe, glisser un widget sur la surface puis choisir son entité HA dans les propriétés. <strong>Interrupteur, variateur, lumière colorée, thermostat et mesure</strong> existent en <strong>tuile</strong> et en <strong>marqueur sur plan avec fenêtre contextuelle</strong> : dix entrées. Position et dimensions restent libres ; il ne s’agit pas d’une grille adaptative automatique. Les cinq groupes CSS standard sont disponibles ; les nouveaux groupes optionnels restent désactivés. Langues des widgets : DE/EN/FR ; interface générale de Studio : DE/EN.</p><p><img src="'+t+'" alt="Tuiles et marqueurs sur plan, démonstration locale"></p><table tabindex="0"><thead><tr><th>Widget</th><th>Source et commandes</th></tr></thead><tbody><tr><td>Interrupteur</td><td><code>switch</code>, <code>light</code> ou <code>input_boolean</code> ; marche/arrêt</td></tr><tr><td>Variateur</td><td><code>light</code> ; luminosité selon les capacités HA</td></tr><tr><td>Lumière colorée</td><td><code>light</code> ; marche/arrêt, luminosité et RGB selon les modes pris en charge</td></tr><tr><td>Thermostat</td><td><code>climate</code> ; consigne unique respectant limites et pas natifs</td></tr><tr><td>Mesure</td><td>État et unité ; lecture seule</td></tr></tbody></table><p>Le mode d’exécution propose uniquement les commandes prises en charge par l’entité. <strong>Lecture seule</strong> interdit l’écriture. L’éditeur ne commande aucun appareil ; les entités indisponibles sont désactivées. La validation serveur reste active. Une requête acceptée ne confirme pas le retour physique de l’appareil. Pour les fonctions avancées comme les plages de température, utiliser <a href="./ha-quellen-climate">Technic/Climate</a>.</p><h2 id="retour-de-tablette-et-page-d-accueil" tabindex="-1">Retour de tablette et page d’accueil <a class="header-anchor" href="#retour-de-tablette-et-page-d-accueil" aria-label="Permalink to &quot;Retour de tablette et page d’accueil&quot;">​</a></h2><p>Dans <strong>Paramètres → Général</strong>, l’option d’actualisation au retour de la tablette recharge les valeurs HA lorsque la page redevient visible, est restaurée ou retrouve le réseau. La page entière n’est pas rechargée. Les temporisateurs suspendus par le navigateur ou la tablette sont pris en compte au retour.</p><p>Le délai et la page d’accueil après inactivité désignent une page visible du projet courant. <strong>0 seconde = désactivé</strong>, valeur par défaut. Les dialogues ouverts, écritures en cours et modifications actives reportent la navigation. Aucun réglage kiosque ni droit d’accès n’est modifié.</p><p><img src="'+a+'" alt="Vue à 1280 × 800, démonstration locale"></p><p><img src="'+s+'" alt="Fenêtre de lumière sur tablette, démonstration locale"></p><h2 id="valeurs-dans-les-titres" tabindex="-1">Valeurs dans les titres <a class="header-anchor" href="#valeurs-dans-les-titres" aria-label="Permalink to &quot;Valeurs dans les titres&quot;">​</a></h2><p>Les titres des cadres et appareils peuvent afficher un état HA ou un attribut, avec décimales et unité. Sélectionner l’entité et l’attribut éventuel dans le groupe de propriétés correspondant. Les titres existants sont conservés ; les valeurs HA sont insérées comme texte.</p><h2 id="rendu-et-capacites-des-paquets" tabindex="-1">Rendu et capacités des paquets <a class="header-anchor" href="#rendu-et-capacites-des-paquets" aria-label="Permalink to &quot;Rendu et capacités des paquets&quot;">​</a></h2><p>Appareils, météo, pièces chauffées, vue des fenêtres, notification au propriétaire, listes d’états Technic et palettes Material chargent leurs modules de rendu à la demande. Les modules communs de l’éditeur restent chargés normalement. Les demandes simultanées partagent un chargement.</p><p>Les manifestes installés sont vérifiés toutes les <strong>30 secondes</strong> et au retour. Les modifications actualisent la palette sans redémarrage. Cela n’installe pas automatiquement les mises à jour proposées dans le catalogue. Un remplacement invalide conserve le catalogue précédent ; les définitions retirées restent en mémoire pour les projets ouverts mais disparaissent de la palette des nouveaux widgets. Les projets ne sont pas migrés automatiquement. Voir <a href="./widget-packages">l’installation des paquets</a>.</p><p><code>optionalCapabilities</code> est une déclaration optionnelle du manifeste : <code>entity-state</code>, <code>history</code>, <code>light-color</code>, <code>climate</code>. La liste indique leur prise en charge. Une capacité inconnue ne donne aucun droit. Les anciens manifestes restent valides ; les commandes dépendent toujours de HA et des capacités de l’entité.</p><p><img src="'+r+'" alt="Import avec deux widgets et affichage des capacités sur .177"></p><h2 id="verification-et-limites" tabindex="-1">Vérification et limites <a class="header-anchor" href="#verification-et-limites" aria-label="Permalink to &quot;Vérification et limites&quot;">​</a></h2><p>Le <strong>8 novembre 2026</strong>, tests sur <strong>.177 / HA 2026.11.0 / Raspberry Pi 5 ARM64</strong> et <strong>.193 / HA 2026.10.4 / Proxmox amd64</strong> : sauvegarde/rechargement du projet, commande réelle d’un assistant HA temporaire avec retour d’état et retour après inactivité. Sur .177, dialogue du marqueur et import local manuel du paquet 1.1.0 avec deux widgets et affichage des capacités également vérifiés. Paquet et assistants de test ensuite supprimés ; délai remis à 0 seconde. Studio reste installé sur les deux systèmes, projets et réglages existants conservés.</p><p>Luminosité, RGB et thermostat testés avec des entités locales simulées. Vues contrôlées dans un navigateur de bureau à 1440 × 1000 et dans une vue tablette à 1280 × 800. Cela ne confirme ni une tablette physique ni tous les types de lampes/chauffages. 394 vérifications JavaScript et 109 Python réussies, plus 7 vérifications JavaScript ciblées et 17 Python pour les paquets. <a href="https://github.com/rockbaer2007/ugso-ha-mqtt-addons/blob/master/ha_grafik_visual_studio/docs/devices-tablet-0.1.297.md" target="_blank" rel="noreferrer">Rapport technique</a>.</p><p>Implémentation HA indépendante sans code ni illustrations VIS-2 copiés. Web Components et conteneur de grille adaptative restent des projets ultérieurs distincts.</p>',23)])])}const q=i(u,[["render",d]]);export{b as __pageData,q as default};
